touchComponent.event:
local tvars = element:templateVars() if tvars.downSpriteName ~= "''" then element["UpSprite"]("visible"):SetInt(1) element["DownSprite"]("visible"):SetInt(0) else element["UpSprite"]:setColor(1.0, 1.0, 1.0) end element["Text"]:setColor(tvars.textTintR, tvars.textTintG, tvars.textTintB)
if("$sfx" ~= "") then lua_sys.playSoundFx("$sfx") end element("ButtonState"):SetInt(game.BUTTON_RELEASED) element("TickTimer"):SetFloat(0.0)
if tvars.lockEnabled == 1 then element("isCurrentlyLocked"):SetInt(1) element("prevTouchState"):SetInt(1) component("enabled"):SetInt(0) end

template.event:
local tvars = element:templateVars() local buttonState = element("ButtonState"):GetInt() local isLocked = element("isCurrentlyLocked"):GetInt()
if(buttonState ~= game.BUTTON_IDLE or isLocked == 1) then local buttonSize = element.spriteScale local newTime = element("TickTimer"):GetFloat() + dt element("TickTimer"):SetFloat(newTime)
if(buttonState == game.BUTTON_PRESSED) then local size = lua_sys.smooth(buttonSize, buttonSize - 0.03, newTime*15) element["UpSprite"]("size"):SetFloat(size)
if(size == buttonSize - 0.03) then element("ButtonState"):SetInt(game.BUTTON_IDLE) end elseif(buttonState == game.BUTTON_RELEASED) then if(newTime < 0.1) then local size = lua_sys.smooth(buttonSize - 0.03, buttonSize + 0.05, newTime*20) element["UpSprite"]("size"):SetFloat(size)
elseif(newTime < 0.3) then local size = lua_sys.smooth(buttonSize + 0.05, buttonSize, (newTime-0.1)*20) element["UpSprite"]("size"):SetFloat(size)
if(size == buttonSize) then element("ButtonState"):SetInt(game.BUTTON_IDLE) end else element["UpSprite"]("size"):SetFloat(buttonSize) element("ButtonState"):SetInt(game.BUTTON_IDLE) end end end
if tonumber(tvars.buttonMapping) ~= 0 or tonumber(tvars.buttonMappingAlt) ~= 0 then if(not element["Touch"]:onTop() and element("buttonDown"):GetInt() ~= 0) then element("buttonDown"):SetInt(0) element["Touch"]:DoStoredScript("onTouchRelease") end end
if(isLocked == 1 and element("TickTimer"):GetFloat() > 1) then element("isCurrentlyLocked"):SetInt(0) -- Uses real state so that if menu is closed during lock, the button does not become clickable. prevTouchState always set on touchUp -- kinda hacky since prevTouchState is only unset on disable and setInvis, so can be bypassed if files don't call the stored scripts. element["Touch"]("enabled"):SetInt(element("prevTouchState"):GetInt()) end
